compatible.keydesc:
{
"en":"Turn off simulated touch",
"ch":"关闭模拟触摸"
}

compatible.notes:
{
"en":"Turn off simulated touch: Solve the problem of remote control applications being unable to operate the scroll wheel.",
"ch":"关闭模拟触摸：解决远控类应用无法操作滚轮的问题。"
}

compatible.keydesc:
{
"en":"Disable window resizing",
"ch":"禁止窗口大小调整"
}

compatible.notes:
{
"en":"Disable window resizing: Some applications do not support dynamic resizing",
"ch":"禁止窗口大小调整：部分应用不支持动态调整大小"
}
